INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('lu-chunqiu','鲁','["鲁","鲁国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-1042,"month":1,"confidence":"year"},"end":{"year":-256,"month":12,"confidence":"year"}}]}','cn','east_asia',-1042,1,NULL,'year',-256,12,NULL,'year',-12492,-3049,'ochre',NULL,NULL,'周武王封周公旦于鲁，周公留辅王室，其子伯禽就封，鲁国以曲阜为中心。鲁长期保存周礼，是孔子的故乡；春秋后期季孙、叔孙、孟孙三家逐步掌权，前256年楚灭鲁。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bo-qin','伯禽','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','周公旦之子。周初周公留在王室辅政，伯禽代表父亲就封于鲁，以曲阜为中心建立统治；传世记载称其参与平定东方叛乱并征服淮夷。具体在位起讫及传统积年仍有异说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伯禽"}]',NULL,NULL,'伯禽','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r1','酋','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','伯禽之子酋，谥考公，在位四年，为鲁国第二代君主，世次见《史记·鲁周公世家》，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁考公"}]','考公',NULL,'鲁考公','[]');
