INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r34','仇','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文公之子仇，谥顷公，鲁国末代君主，前279年至前256年在位。前256年楚考烈王灭鲁，顷公迁于下邑，成为平民；前249年卒于柯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁顷公"},{"label":"《史记·鲁周公世家》","url":"https://zh.wikisource.org/wiki/史記/卷033"}]','顷公',NULL,'鲁顷公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r4','晞','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','幽公之子晞，谥魏公，在位近五十年，为鲁国西周时期在位时间较长之君，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁魏公"}]','魏公',NULL,'鲁魏公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r5','擢','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','魏公之子擢，谥厉公，在位三十七年，属西周晚期鲁国君主，除世次外史料有限，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁厉公"}]','厉公',NULL,'鲁厉公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r6','具','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','厉公之子具，谥献公，在位约三十二年，承续鲁国世系，事迹记载甚少，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁献公"}]','献公',NULL,'鲁献公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r7','濞','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','献公之子濞，谥真公，在位约三十年，为春秋以前鲁国世君之一，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁真公"}]','真公',NULL,'鲁真公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r8','敖','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','真公之子敖，谥武公，在位九年，承续鲁国嫡系，事迹除世次外记载有限，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁武公"}]','武公',NULL,'鲁武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-r9','戏','lu-chunqiu','[]','姬','鲁',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武公之子戏，谥懿公，在位九年，后被侄伯御所弑，鲁国再度陷入内争，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁懿公"}]','懿公',NULL,'鲁懿公','[]');
